final void unite(int x, int y, int p) {
    int rootx = getRoot(x);
    int rooty = getRoot(y);
    if (rootx == rooty) {
        return;
    }
    if (size[rootx] < size[rooty]) {
        int tmp = rootx;
        rootx = rooty;
        rooty = tmp;
    }
    parent[rooty] = rootx;
    dist[rooty] = p + dist[x] - dist[y];
    size[rootx] += size[rooty];
